import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Damping Theory — Revised","description":"","frontmatter":{"translationSource":{"title":"阻尼理论-改","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=WJNJBOl9tQtVZ0GEuD8UaP","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revised"}]]},"headers":[],"relativePath":"damping-theory-revised.md","filePath":"logistics/src/page-WJNJBOl9tQtVZ0GEuD8UaP.md"}'),n={name:"damping-theory-revised.md"};function r(s,e,p,d,l,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="阻尼理论-改" aria-hidden="true"></span><h1 id="damping-theory-—-revised" tabindex="-1">Damping Theory — Revised <a class="header-anchor" href="#damping-theory-—-revised" aria-label="Permalink to &quot;Damping Theory — Revised&quot;">​</a></h1><blockquote><p>Source page ID: <code>WJNJBOl9tQtVZ0GEuD8UaP</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=WJNJBOl9tQtVZ0GEuD8UaP" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Damping theory was created and is compiled/maintained by @jnk. The current version lacks sufficient verification.</p><p><span class="mark-red">Damping theory is outdated. For the latest theory see </span><a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>. The images here have been removed because this material has been archived and to avoid duplication.</p><p>Input/output priority in Reactor Crucibles and Expanded Crucibles is a special case outside this theory. See <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NWZEGRxknMJsjvUO7PQZXj&amp;client_hint=0" target="_blank" rel="noreferrer">Compilation of Reactor Crucible Properties</a>.</p><p>The terminology here uses <em>logistics paths</em>:</p><p>A logistics path is any possible item route from a factory output to the end of a logistics network, as marked in red. If no factory is connected at the end, treat the terminal logistics component as a factory. All intermediate logistics components are part of the path.</p><p><em>Damping of a logistics path:</em></p><p>Its damping is the number of logistics components on it. A whole belt counts as one component; different Belt Bridge directions count separately. A splitter flush against a factory input, with other downstream connections, ignores the path to that factory. It likewise does not affect subsequent determination of connection order.</p><p><em>Terminal order (connection order):</em></p><p>Specifically, when a logistics component connects directly to a factory input:</p><p>If it is not a splitter and a non-splitter on another input of that factory is already in the terminal order, add it to that existing non-splitter entry; otherwise append it at the end.</p><p>When the component or connected factory is deleted, it is removed from connection order, and related placement-order changes are recalculated. For example, once a path becomes open-ended, its terminal component is treated as an already-existing factory.</p><p>Terminal order is also input priority: an earlier entry has higher priority; components in the same entry are serviced round-robin.</p><p><span class="mark-red">Add a worked diagram here.</span></p><p><em>Output damping:</em></p><p>An output may correspond to multiple paths but selects only one path&#39;s damping as its output damping. Thus every output has just one damping value. See damping theory for the calculation.</p><p><em>Damping theory:</em></p><p>A theory explaining why factory outputs sometimes have priorities. The term usually refers to explaining output priority.</p><p>Take one entry of terminal logistics components from terminal order; it may contain several merged components:</p><p>Perform BFS from downstream to upstream, marking upstream damping as downstream damping plus one. Add visited markers to prevent revisits.</p><p>Handle a single component at a factory output with no downstream connection specially. If it was connected before the upstream factory, its damping is positive infinity, immune to assimilation; otherwise it is an infinitesimal value, subject to assimilation.</p><p>For multiple outputs of one factory, set all outputs not beginning with convergers to their common maximum damping. This is called assimilation.</p><p>Finally, lower damping gives higher priority; an output whose first logistics component was placed earlier has higher precedence. Compare priority first, then precedence. Among outputs not beginning with convergers, if prioritized, service them round-robin.</p><p><span class="mark-red">Add a worked diagram here.</span></p></div>',1)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
